/** TEMP PS S1635 vl2 — laiško šaltinis: mu + plugins + snippets + options. READ-ONLY. */
add_action('init', function(){
  if (!isset($_GET['ps_s1635vl2'])) return;
  global $wpdb; $p=$wpdb->prefix; $o=array('v'=>'vl2');
  $wpdb->query("DELETE FROM {$p}snippets WHERE name LIKE 'TEMP%' AND active=0");
  $ADATA='Ar su užsakymu viskas gerai';
  $r=$wpdb->get_row($wpdb->prepare("SELECT id,name FROM {$p}snippets WHERE code LIKE %s LIMIT 1",'%'.$wpdb->esc_like($ADATA).'%'),ARRAY_A);
  if($r){ $o['snippet']=$r; $c=$wpdb->get_var($wpdb->prepare("SELECT code FROM {$p}snippets WHERE id=%d",$r['id']));
    $pos=mb_strpos($c,$ADATA); $o['kont']=mb_substr($c,max(0,$pos-2000),3000); }
  if(!$r){ $rows=$wpdb->get_results($wpdb->prepare("SELECT option_name FROM {$p}options WHERE option_value LIKE %s LIMIT 5",'%'.$wpdb->esc_like($ADATA).'%')); foreach($rows as $x) $o['opcijos'][]=$x->option_name;
    foreach(glob(WP_PLUGIN_DIR.'/petshop*/*.php') as $g){ $s=file_get_contents($g); if(strpos($s,$ADATA)!==false){ $o['failas']=str_replace(WP_PLUGIN_DIR,'',$g); $pos=strpos($s,$ADATA); $o['kont']=mb_substr($s,max(0,$pos-2000),3000); break; } } }
  header('Content-Type: application/json'); echo json_encode($o,JSON_UNESCAPED_UNICODE); exit;
},99);
